const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([-107.202, 33.155]).buffer(15000); // Elephant Butte Reservoir, NM
    const date1986 = ee.Date('1986-06-12');
    const date2020 = ee.Date('2020-06-09');
    const scale = 100; // Use a reasonable scale for regional analysis

    // 2. Data Acquisition & Processing Functions
    // Function to mask clouds, shadows, snow, and water for Landsat 4, 5, 7
    function maskL457sr(image) {
        const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
        return image.updateMask(qaMask);
    }

    // Function to mask clouds, shadows, snow, and water for Landsat 8, 9
    function maskL8sr(image) {
        const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
        return image.updateMask(qaMask);
    }

    // Function to calculate NDWI and derive a water mask
    const getWaterMask = (image, nirBand, greenBand) => {
        const ndwi = image.normalizedDifference([greenBand, nirBand]);
        return ndwi.gt(0); // Common threshold for water
    };

    // --- Period 1: 1986 ---
    const collection1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(date1986.advance(-15, 'day'), date1986.advance(15, 'day'));

    const count1986 = collection1986.size().getInfo();
    if (count1986 === 0) {
        console.log("Evidence: No Landsat 5 images found for the 1986 period.");
        console.log("A: No");
        return;
    }

    const image1986 = ee.Image(collection1986.map(maskL457sr).median().clip(geometry));
    const water1986 = getWaterMask(image1986, 'SR_B4', 'SR_B2');

    // --- Period 2: 2020 ---
    const collection2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(geometry)
        .filterDate(date2020.advance(-15, 'day'), date2020.advance(15, 'day'));

    const count2020 = collection2020.size().getInfo();
    if (count2020 === 0) {
        console.log("Evidence: No Landsat 8 images found for the 2020 period.");
        console.log("A: No");
        return;
    }

    const image2020 = ee.Image(collection2020.map(maskL8sr).median().clip(geometry));
    const water2020 = getWaterMask(image2020, 'SR_B5', 'SR_B3');

    // 3. Calculation
    const pixelArea = ee.Image.pixelArea();
    const waterArea1986 = water1986.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('nd');

    const waterArea2020 = water2020.multiply(pixelArea).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    }).get('nd');

    // Execute computations
    const area1986_sqkm = ee.Number(waterArea1986).divide(1e6).getInfo();
    const area2020_sqkm = ee.Number(waterArea2020).divide(1e6).getInfo();

    // 4. Validation & Final Answer
    if (area1986_sqkm === null || area2020_sqkm === null) {
        console.log("Evidence: Calculation failed, one or both areas returned null.");
        console.log(`1986 Area: ${area1986_sqkm}, 2020 Area: ${area2020_sqkm}`);
        console.log("C3: Calculation Failure");
        return;
    }

    if (area1986_sqkm === 0 || area2020_sqkm === 0) {
        console.log("Evidence: No water pixels detected in one of the periods after processing.");
        console.log(`1986 Water Area (km^2): ${area1986_sqkm.toFixed(2)}`);
        console.log(`2020 Water Area (km^2): ${area2020_sqkm.toFixed(2)}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    console.log(`Evidence:`);
    console.log(`Image count (1986): ${count1986}`);
    console.log(`Image count (2020): ${count2020}`);
    console.log(`1986 Water Area (km^2): ${area1986_sqkm.toFixed(2)}`);
    console.log(`2020 Water Area (km^2): ${area2020_sqkm.toFixed(2)}`);

    if (area2020_sqkm < area1986_sqkm) {
        console.log("Conclusion: Water extent decreased.");
        console.log("A: Yes");
    } else {
        console.log("Conclusion: Water extent did not decrease.");
        console.log("B: No");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error("Error during Earth Engine initialization or analysis:", e);
        console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
    }
}

initEE();
